usage:
```js
const EventEmitter = require('bare-events')

const e = new EventEmitter()

e.on('hello', function (data) {
  console.log(data)
})

e.emit('hello', 'world')
```

signatures:
interface AbortSignal {
  addEventListener(
    type: string,
    callback: EventListener,
    options?: AddEventListenerOptions | boolean
  ): void
  removeEventListener(
    type: string,
    callback: EventListener,
    options?: RemoveEventListenerOptions | boolean
  ): void
  dispatchEvent(event: Event): boolean
}

interface EventOptions {
  bubbles?: boolean
  cancelable?: boolean
  composed?: boolean
}

interface CustomEventOptions<T = any> {
  detail?: T
  bubbles?: boolean
  cancelable?: boolean
  composed?: boolean
}

interface AddEventListenerOptions {
  capture?: boolean
  passive?: boolean
  once?: boolean
  signal?: AbortSignal | null
}

interface EventTarget {
  addEventListener(
    type: string,
    callback: EventListener,
    options?: AddEventListenerOptions | boolean
  ): void
  removeEventListener(
    type: string,
    callback: EventListener,
    options?: RemoveEventListenerOptions | boolean
  ): void
  dispatchEvent(event: Event): boolean
}
